#define WF_ROM_CYCLES_N ((int)(sizeof wf_rom_cycles / sizeof wf_rom_cycles[0]))

/* Cost of one instruction. `taken` matters only for conditional branches.
 * Returns 0 for a PC outside the table, which means the caller's path is
 * wrong rather than the instruction being free. */
static int wf_rom_cycle_at(unsigned pc, int taken)
{
    int lo = 0, hi = WF_ROM_CYCLES_N - 1;

    while (lo <= hi) {
        int mid = (lo + hi) / 2;

        if (wf_rom_cycles[mid].pc == pc)
            return wf_rom_cycles[mid].cycles
                 + (taken ? 0 : wf_rom_cycles[mid].notake_adj);
        if (wf_rom_cycles[mid].pc < pc)
            lo = mid + 1;
        else
            hi = mid - 1;
    }
    return 0;
}

/* Straight-line cost of [from, to]. Only valid for a run with no conditional
 * branch inside it; charge those individually with wf_rom_cycle_at(). */
static int wf_rom_cycle_run(unsigned from, unsigned to)
{
    int i, sum = 0;

    for (i = 0; i < WF_ROM_CYCLES_N; i++)
        if (wf_rom_cycles[i].pc >= from && wf_rom_cycles[i].pc <= to)
            sum += wf_rom_cycles[i].cycles;
    return sum;
}

